159	    /**
160	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
161	     * Not persisted — derived from {@link #getLastName()} and {@link #getFirstName()}.
162	     */
163	    @Transient
164	    public String getDisplayName() {
