168	    /**
169	     * The owner's initials: the upper-cased first letters of firstName and lastName,
170	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
171	     * Not persisted — derived from {@link #getFirstName()} and {@link #getLastName()}.
172	     */
173	    @Transient
