179	    /**
180	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
181	     * the last two digits of the {@link #getRegistrationDate() registrationDate} year
182	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}).
183	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
184	     */
185	    @Transient
186	    public String getMembershipNumber() {
187	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
188	    }
