190	    /**
191	     * The owner's check digit: the Luhn check digit (0-9) computed over the digits contained
192	     * in the {@link #getCustomerCode() customerCode}. Non-digit characters are ignored.
193	     * Not persisted — derived from {@link #getCustomerCode()}.
194	     */
195	    @Transient
196	    public int getCheckDigit() {
197	        int sum = 0;
198	        boolean dbl = true;
199	        String code = this.customerCode == null ? "" : this.customerCode;
200	        for (int i = code.length() - 1; i >= 0; i--) {
201	            char c = code.charAt(i);
202	            if (c < '0' || c > '9') {
203	                continue;
204	            }
205	            int d = c - '0';
206	            if (dbl) {
207	                d *= 2;
208	                if (d > 9) {
209	                    d -= 9;
210	                }
211	            }
212	            sum += d;
213	            dbl = !dbl;
214	        }
215	        return (10 - (sum % 10)) % 10;
216	    }
