238	    /**
239	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
240	     */
241	    private static final Map<String, String> CITY_REGION = Map.of(
242	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
