244	    /**
245	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
246	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
247	     */
248	    private static final Map<String, int[]> REGION_RANGE = Map.of(
249	        "NSW", new int[] {2000, 2099},
250	        "VIC", new int[] {3000, 3099},
251	        "QLD", new int[] {4000, 4099});
252	
253	    /**
254	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
255	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
256	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
257	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
258	     * the owner's {@link #getCustomerCode() customerCode}, so the create pipeline and
259	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
260	     * by the owner pipelines (e.g. postcode validation) rather than copied.
261	     */
262	    public static String regionFor(String postcode, String city) {
263	        String region = regionForPostcode(postcode);
264	        if (region != null) {
265	            return region;
266	        }
267	        String cityRegion = regionForCity(city);
268	        return cityRegion != null ? cityRegion : "UNKNOWN";
269	    }
270	
271	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
272	     * Brisbane->QLD), or {@code null} when the city has no known region. */
273	    public static String regionForCity(String city) {
274	        return city == null ? null : CITY_REGION.get(city);
275	    }
276	
277	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
278	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
279	     * range. */
280	    public static String regionForPostcode(String postcode) {
281	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
282	            return null;
283	        }
284	        int value = Integer.parseInt(postcode);
285	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
286	            int[] range = entry.getValue();
287	            if (value >= range[0] && value <= range[1]) {
288	                return entry.getKey();
289	            }
290	        }
291	        return null;
292	    }
